const id = String($input.first().json.body?.store_id ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) {
  throw new Error('store_id 형식 오류');
}
return [{ json: { store_id: id, triggered_by: 'USER' } }];

const uuid = () => {
  const h = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-${'89ab'[Math.floor(Math.random() * 4)]}${h.slice(17, 20)}-${h.slice(20, 32)}`;
};
const s = $input.first().json;
return [{ json: { store_id: s.store_id, triggered_by: s.triggered_by, job_id: uuid() } }];

const job = $('작업 시작').first().json;
const daily = $('일별 매출').all().map((i) => i.json).filter((r) => r.date);
const menus = $('메뉴별 판매').all().map((i) => i.json).filter((r) => r.date);
const last = daily.length ? daily[daily.length - 1].date : null;
const add = (d, n) => {
  const t = new Date(`${d}T00:00:00Z`);
  t.setUTCDate(t.getUTCDate() + n);
  return t.toISOString().slice(0, 10);
};
const weather = $('날씨').first().json.weather ?? [];
return [{ json: { body: {
  store_id: job.store_id,
  target_dates: last ? [1, 2, 3].map((n) => add(last, n)) : [],
  sales_history: daily.map((r) => ({ date: r.date, total_amount: Number(r.total_amount), order_count: Number(r.order_count) })),
  menu_sales_history: menus.map((r) => ({ date: r.date, menu_id: r.menu_id, quantity: Number(r.quantity) })),
  weather,
} } }];

const b64 = (s) => (typeof Buffer !== 'undefined'
  ? Buffer.from(s, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(s))));
const job = $('작업 시작').first().json;
const rows = $input.first().json.predictions.map((p) => ({
  target_date: p.target_date, horizon_days: p.horizon_days, predicted_sales: p.predicted_sales,
  interval_p10: p.interval_p10, interval_p90: p.interval_p90,
  is_low_confidence: p.is_low_confidence ? 1 : 0, low_confidence_reason: p.low_confidence_reason ?? null,
  explanation: p.explanation ?? null, menu_forecast: p.menu_forecast ?? [],
}));
return [{ json: { job_id: job.job_id, store_id: job.store_id, payload: b64(JSON.stringify(rows)) } }];

const b64 = (s) => (typeof Buffer !== 'undefined'
  ? Buffer.from(s, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(s))));
const job = $('작업 시작').first().json;
const raw = $input.first().json;
const e = raw.error ?? raw;
const msg = String((typeof e === 'string' ? e : e.message ?? e.description) ?? JSON.stringify(e)).slice(0, 480);
// AI Server 422 = 판매 이력 부족 — 재시도·Slack 대상이 아니다 (01_basic_design.md §3.11.1)
const insufficient = /\b422\b/.test(msg);
return [{ json: { job_id: job.job_id, store_id: job.store_id, status: 'FAILED',
  insufficient_history: insufficient, error: msg, error_b64: b64(msg) } }];

const results = $input.all().map((i) => i.json);
if (results.length === 1) return [{ json: results[0] }];
return [{ json: {
  status: results.every((r) => r.status === 'DONE') ? 'DONE' : 'PARTIAL',
  stores: results.length, failed: results.filter((r) => r.status !== 'DONE').length,
} }];

// 날씨 — 판매 이력 기간과 어제까지의 대상일은 ASOS 일자료, 오늘 이후 대상일은 단기예보 (01_basic_design.md §3.11.1).
// 위치가 없거나 호출이 실패하면 그 날짜를 빼고 진행한다 — 날씨 실패로 작업을 실패시키지 않는다.
const loc = $('매장 위치').first().json;
const daily = $('일별 매출').all().map((i) => i.json).filter((r) => r.date);
const key = $env.KMA_SERVICE_KEY;
const API = 'https://apis.data.go.kr/1360000';
const notes = [];

const add = (d, n) => {
  const t = new Date(`${d}T00:00:00Z`);
  t.setUTCDate(t.getUTCDate() + n);
  return t.toISOString().slice(0, 10);
};
const ymd = (d) => d.replaceAll('-', '');
const kstNow = new Date(Date.now() + 9 * 3600 * 1000); // UTC 게터로 한국 시각을 읽는다
const today = kstNow.toISOString().slice(0, 10);
const yesterday = add(today, -1);

const get = async (path, qs) => {
  let last;
  for (let i = 0; i < 3; i++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: `${API}/${path}`, json: true, timeout: 20000,
        qs: { serviceKey: key, dataType: 'JSON', ...qs },
      });
      const head = res?.response?.header;
      if (head?.resultCode !== '00') throw new Error(`${head?.resultCode} ${head?.resultMsg}`);
      return res.response.body;
    } catch (e) {
      last = e;
      await new Promise((r) => setTimeout(r, 2000));
    }
  }
  throw last;
};
const getAll = async (path, qs, rows) => {
  const items = [];
  for (let page = 1; ; page++) {
    const body = await get(path, { ...qs, pageNo: page, numOfRows: rows });
    const got = body?.items?.item ?? [];
    items.push(...got);
    if (!got.length || items.length >= Number(body.totalCount ?? 0)) return items;
  }
};
const num = (v) => (v === '' || v == null || Number.isNaN(Number(v)) ? null : Number(v));
// 단기예보 PCP — '강수없음' 0, '1mm 미만' 0.5, 'a~bmm' a, '50.0mm 이상' 50, 'xmm' x
const pcp = (v) => {
  const s = String(v ?? '').trim();
  if (!s || s === '강수없음') return 0;
  if (s.includes('미만')) return 0.5;
  const m = s.match(/[\d.]+/);
  return m ? Number(m[0]) : 0;
};

const last = daily.length ? daily[daily.length - 1].date : null;
const targets = last ? [1, 2, 3].map((n) => add(last, n)) : [];
const weather = new Map();

if (!loc?.asos_stn_id || !loc?.kma_nx || !key || !daily.length) {
  notes.push('위치·서비스키·판매 이력 중 없는 것이 있어 날씨 없이 예측');
} else {
  // 과거 관측 — 판매 이력 첫날부터 min(어제, 마지막 대상일)까지
  const end = [yesterday, targets[targets.length - 1]].sort()[0];
  if (daily[0].date <= end) {
    try {
      const items = await getAll('AsosDalyInfoService/getWthrDataList', {
        dataCd: 'ASOS', dateCd: 'DAY', startDt: ymd(daily[0].date), endDt: ymd(end),
        stnIds: loc.asos_stn_id,
      }, 999);
      for (const it of items) {
        const lo = num(it.minTa);
        const hi = num(it.maxTa);
        if (lo == null || hi == null) continue;
        weather.set(it.tm, { date: it.tm, temp_min: lo, temp_max: hi, rainfall_mm: num(it.sumRn) ?? 0 });
      }
    } catch (e) {
      notes.push(`ASOS 실패: ${e.message ?? e}`);
    }
  }

  // 대상일 예보 — 오늘 02시 발표(02:10 전이면 전날 23시 발표). 그 뒤 발표는 지나간 오늘 TMN·TMX가 빠진다
  const future = targets.filter((d) => d >= today);
  if (future.length) {
    const early = kstNow.getUTCHours() * 60 + kstNow.getUTCMinutes() < 2 * 60 + 10;
    const baseDate = ymd(early ? yesterday : today);
    const baseTime = early ? '2300' : '0200';
    try {
      const items = await getAll('VilageFcstInfoService_2.0/getVilageFcst', {
        base_date: baseDate, base_time: baseTime, nx: loc.kma_nx, ny: loc.kma_ny,
      }, 1000);
      const byDate = {};
      for (const it of items) {
        const d = `${it.fcstDate.slice(0, 4)}-${it.fcstDate.slice(4, 6)}-${it.fcstDate.slice(6, 8)}`;
        const day = (byDate[d] ??= { tmp: [], rain: 0 });
        if (it.category === 'TMN') day.tmn = num(it.fcstValue);
        if (it.category === 'TMX') day.tmx = num(it.fcstValue);
        if (it.category === 'TMP' && num(it.fcstValue) != null) day.tmp.push(num(it.fcstValue));
        if (it.category === 'PCP') day.rain += pcp(it.fcstValue);
      }
      for (const d of future) {
        const day = byDate[d];
        if (!day) continue;
        // TMN·TMX가 빠진 날은 1시간 기온의 최저·최고로 채운다
        const lo = day.tmn ?? (day.tmp.length ? Math.min(...day.tmp) : null);
        const hi = day.tmx ?? (day.tmp.length ? Math.max(...day.tmp) : null);
        if (lo == null || hi == null) continue;
        weather.set(d, { date: d, temp_min: lo, temp_max: hi, rainfall_mm: Math.round(day.rain * 10) / 10 });
      }
    } catch (e) {
      notes.push(`단기예보 실패: ${e.message ?? e}`);
    }
  }
}

return [{ json: {
  weather: [...weather.values()].sort((a, b) => (a.date < b.date ? -1 : 1)),
  notes,
} }];
